    code: 'Subcapitolul 5.2',
    title: '5.2. Neurobiologia deciziei sub stres acut și opoziția dintre bucla reactivă dezadaptativă (Track A) și traseul deliberativ adaptativ (Track B) (Figura 6 și Tabelul 1)',
    dominantStrata: ['B', 'C'],
